            replace(replace(i."ReturnedDeliveryData",
              '"EventTime":"' || (CASE WHEN i."ReturnedDeliveryData" IS JSON OBJECT THEN i."ReturnedDeliveryData"::json #>> '{Events,0,EventTime}' END) || '"',
